import pytest
from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def sum_squares_with(xs: list[int], workers: int) -> int:
    """Sum of square(x) for every x in xs, with the squares computed in a
    thread pool of `workers` threads.

    The result is identical for every worker count. Returns 0 for an empty
    list. Does not modify xs. Raises ValueError if workers < 1, even when xs
    is empty.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def sum_squares(xs: list[int]) -> int:
    """Sum of the squares of every element of xs, computed in parallel with
    a thread pool using a default worker count.

    Equal to sum_squares_with(xs, w) for any valid w. Returns 0 for an
    empty list.
    """
    return sum_squares_with(xs, 4)


WORKER_COUNTS = [1, 2, 3, 4, 8, 64]


def reference(xs: list[int]) -> int:
    return sum(x * x for x in xs)


def test_square_given() -> None:
    assert square(-3) == 9
    assert square(0) == 0


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_sum_squares_empty() -> None:
    assert sum_squares([]) == 0


def test_sum_squares_single_and_negatives() -> None:
    assert sum_squares([-5]) == 25
    assert sum_squares([-1, 1, -2, 2]) == 10


def test_sum_squares_big_ints() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_same_result_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 51)) + [7, 7, 7, 1000]
    assert sum_squares_with(xs, workers) == reference(xs)
    assert sum_squares_with(xs, workers) == sum_squares(xs)


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_empty_every_worker_count(workers: int) -> None:
    assert sum_squares_with([], workers) == 0


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_fewer_items_than_workers(workers: int) -> None:
    assert sum_squares_with([3, 4], workers) == 25


def test_large_input_all_worker_counts_agree() -> None:
    xs = [(i * 37) % 101 - 50 for i in range(5000)]
    expected = reference(xs)
    results = {sum_squares_with(xs, w) for w in WORKER_COUNTS}
    assert results == {expected}
    assert sum_squares(xs) == expected


def test_order_does_not_matter() -> None:
    xs = [5, -3, 8, 0, 2, 2]
    assert sum_squares_with(xs, 4) == sum_squares_with(xs[::-1], 4)


def test_input_not_mutated() -> None:
    xs = [3, -1, 2]
    copy = list(xs)
    sum_squares_with(xs, 3)
    sum_squares(xs)
    assert xs == copy


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_worker_count(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares_with([1, 2, 3], workers)
    with pytest.raises(ValueError):
        sum_squares_with([], workers)
